import { addEntry } from "../../store";

export async function POST(context) {
  const formData = await context.request.formData();
  const message = (formData.get("message") || "").toString().trim();

  if (message) {
    addEntry(message);
  }

  return new Response(null, {
    status: 303,
    headers: {
      Location: "/guestbook",
    },
  });
}

